  "claims": [
    {
      "claim": "The query is pyridostigmine, a permanently charged quaternary pyridinium dimethylcarbamate; the closest transferable carbamate contexts are physostigmine (poor oral bioavailability) and bambuterol (~10% in healthy adults), both supporting F < 20%.",
      "card_ids": ["C06", "C02", "C04", "C09", "C19"]
    },
    {
      "claim": "L5 neostigmine, the closest quaternary carbamate analog, showed only 12.8% absorption after 2 h in rat jejunal loops, 5.5% under secretory conditions, and 6.6% of the dose trapped in gut wall after 3 h; this is affirmative low-absorption and presystemic-loss evidence for the quaternary carbamate class.",
      "card_ids": ["C51", "C61", "C53"]
    },
    {
      "claim": "C57 shows neostigmine is a P-gp substrate with limited efflux; this does not provide high-absorption evidence and is consistent with low passive permeability rather than efflux-mediated loss.",
      "card_ids": ["C57"]
    },
    {
      "claim": "C58 (low-pH permeability increase) and C54 (osmotic water-flux effects) are mechanistic and not transferable to fasted intestinal F; MPP+ (C52, C59), paraquat (C50, C56, C60), and ESC8 (C55) records concern different molecules and do not bear on the query.",
      "card_ids": ["C58", "C54", "C52", "C59", "C50", "C56", "C60", "C55"]
    },
    {
      "claim": "No L5 record provides a direct absolute oral bioavailability value for pyridostigmine, so the low prediction is retained with moderate confidence.",
      "card_ids": ["C51", "C61", "C53"]
    }
  ],
